   429→                Ok(data_columns) => {
   430→                    send_data_column_count += data_columns.len();
   431→                    for data_column in data_columns {
   432→                        self.send_response(
   433→                            peer_id,
   434→                            inbound_request_id,
   435→                            Response::DataColumnsByRoot(Some(data_column)),
   436→                        );
   437→                    }
   438→                }
   439→                Err(e) => {
   440→                    // TODO(das): lower log level when feature is stabilized
   441→                    error!(
   442→                        block_root = ?data_column_ids_by_root.block_root,
   443→                        %peer_id,
   444→                        error = ?e,
   445→                        "Error getting data column"
   446→                    );
   447→                    return Err((RpcErrorResponse::ServerError, "Error getting data column"));
   448→                }
   449→            }
   450→        }
   451→
   452→        debug!(
   453→            %peer_id,
   454→            request = ?request.data_column_ids,
   455→            returned = send_data_column_count,
   456→            "Received DataColumnsByRoot Request"
   457→        );
   458→
   459→        Ok(())
   460→    }
